function score(x,q){const al=w=>w.replace(/^ال/,'');let s=0;const nw=x.n.split(/\s+/).map(al),kw=x.k.split(/\s+/).map(al),qa=al(q);if(x.n.startsWith(q))s+=8;if(nw.some(w=>w===qa))s+=6;else if(nw.some(w=>w.startsWith(qa)))s+=4;if(kw.some(w=>w===qa))s+=3;else if(kw.some(w=>w.startsWith(qa)))s+=2;if(x.n.includes(q))s+=1;return s}
